def L(pt,en):
    def clean(s):return re.sub(r'([,;:])(?=[A-Za-zÀ-ÿ])', r'\1 ', s)
    return {'pt':clean(pt),'en':clean(en)}
def table(title,cols,rows,note):return {'title':L(*title),'columns':[L(*c) for c in cols],'rows':rows,'note':L(*note)}
