studies=[{'id':'pellegri','cultivar':'Grand Rapids','title':L('Grand Rapids · química e colheita','Grand Rapids · chemistry and harvest'),'summary':L('K reduzido: massa seca aérea 19,2% menor que Controle 2; os dois controles já diferem 13,7%. Contrastes descritivos, não efeitos isolados.','Reduced K: shoot dry mass 19.2% below Control 2; the two controls themselves differ 13.7%. Descriptive contrasts, not isolated effects.'),'design':L('4 ensaios sequenciais de 28 dias; 62 amostras de solução; 10 plantas subamostradas por ensaio compartilhado.','4 sequential 28-day runs; 62 solution samples; 10 plant subsamples per shared run.'),'chemistry':L('NO3, NH4, K, P, Ca, Mg, S, Na, Cl medidos. pH alvo 5,9; EC alvo 1,9 mS/cm ou rampa a 4,6 no NaCl; alvos não são séries medidas.','Measured NO3, NH4, K, P, Ca, Mg, S, Na, Cl. pH target5.9; EC target1.9 mS/cm or ramp to4.6 for NaCl; targets are not measured time series.'),'limitations':L('NaNO3 substitui KNO3: muda mais de um íon. Sequência, equipamento, metais-traço, CO2 e interrupção de controle confundem os contrastes. Sem perclorato.','NaNO3 replaces KNO3: more than one ion changes. Sequence, equipment, trace metals, CO2 and control interruption confound contrasts. No perchlorate.'),'tables':esatables,'source_url':src[0]['url']},
{'id':'bannon','cultivar':'Red Batavia','title':L('Red Batavia · manejo e nutrientes','Red Batavia · management and nutrients'),'summary':L('Troca semanal apresentou +23,0% de massa fresca do componente de rendimento versus reposição de volume, sem teste causal novo.','Weekly replacement showed +23.0% yield-component fresh mass versus top-up, without a new causal test.'),'design':L('3 sistemas por regime em períodos diferentes; 384 posições de colheita, 379 pares numéricos de massa fresca total + componente de rendimento, não 379 tratamentos independentes.','3 systems per regime in different periods;384 harvest slots,379 numeric overall + yield-component fresh-mass pairs,not 379 independent treatments.'),'chemistry':L('NO3 como N, P, K, Ca, Mg, SO4, Fe, Mn e EC. Sem série bruta de pH, Na, Cl ou NH4; sem perclorato.','NO3 as N,P,K,Ca,Mg,SO4,Fe,Mn and EC. No raw pH,Na,Cl or NH4 series; no perchlorate.'),'limitations':L('Manejo confundido com calendário. Cinco posições vazias, um seco ausente; duas inconsistências de massa e proporcionalidades exatas com origem não resolvida. Não inferimos fabricação; requer auditoria humana.','Management confounded with calendar. Five empty slots,one missing dry value; two mass inconsistencies and exact proportionalities with unresolved origin. No fabrication inference; human audit needed.'),'tables':btables,'source_url':src[1]['url']},
{'id':'bruni','cultivar':'Salanova','title':L('Salanova · solução alcalina e contexto biológico','Salanova · alkaline solution and biological context'),'summary':L('Observações de solução pH 7,47–8,36; sobreposição numérica parcial com Phoenix. Não é faixa ótima nem ensaio causal de pH.','Observed solution pH 7.47–8.36; partial numerical overlap with Phoenix. Not an optimum range or causal pH experiment.'),'design':L('20 caixas, uma por combinação completa; 6 plantas por caixa; colheita publicada em três grupos de duas plantas. 380 linhas temporais, apenas 40 perfis iônicos.','20 boxes,one per full combination;6 plants per box; published harvest in three pools of two plants.380 time rows,only 40 ion profiles.'),'chemistry':L('220 leituras de pH;21 linhas com pH,EC e seis íons Na,K,Ca,Mg,SO4,Cl juntos. Bases de nitrato/fosfato não resolvidas.','220 pH readings;21 rows with pH,EC and six ions Na,K,Ca,Mg,SO4,Cl together. Nitrate/phosphate mass bases unresolved.'),'limitations':L('Fonte nutricional, microrganismos e Pythium são fatores cruzados/combinados; uma caixa por célula completa. Sem NH4/perclorato. EC intermediária mistura escalas; apenas endpoints verificados usados.','Nutrient source,microbes and Pythium are crossed/combined factors;one box per full cell. No NH4/perchlorate. Intermediate EC mixes scales;only verified endpoints used.'),'tables':brtables,'source_url':src[3]['url']},
{'id':'ha','cultivar':'Crispino / Adriana','title':L('Perclorato · absorção, não produtividade','Perchlorate · uptake, not productivity'),'summary':L('Perclorato medido em tecidos; crescimento não comprova segurança alimentar. Não aplicamos os modelos publicados à Phoenix.','Perchlorate measured in tissues;growth does not establish food safety. Published models are not applied to Phoenix.'),'design':L('10 receitas,30 tanques de areia,3 por receita; independência dos reservatórios não totalmente resolvida. Cultivares e tecidos do tanque são correlacionados.','10 recipes,30 sand tanks,3 per recipe;reservoir independence not fully resolved. Cultivars and tissues within tank are correlated.'),'chemistry':L('Água: ClO4 nominal40/220/400 nmolc/L (≈4/22/40 µg/L), NO3 2–20 mmolc/L, Cl 2,5–25 mmolc/L. Tecido:µg/kg fresco, LOD1,6.','Water:nominal ClO4 40/220/400 nmolc/L (≈4/22/40 µg/L),NO3 2–20 mmolc/L,Cl 2.5–25 mmolc/L. Tissue:µg/kg fresh weight,LOD1.6.'),'limitations':L('Sem endpoint bruto de biomassa/produtividade; censura não é zero. Sem previsão de tecido, dose alimentar ou aprovação para consumo; coeficientes não republicados; escala dos preditores não resolvida.','No raw biomass/yield endpoint;censoring is not zero. No tissue prediction,dietary dose or consumption clearance;coefficients not republished; predictor scaling unresolved.'),'tables':[table(('Observações abaixo do LOD de tecido','Tissue observations below LOD'),[('Cultivar','Cultivar'),('Folhas externas','Outer leaves'),('Folhas internas','Inner leaves'),('Raízes','Roots')],[['Crispino','0/30','18/30','1/30'],['Adriana','0/30','6/30','5/30']],('Contagens publicadas; censura não é zero. LOD1,6 µg/kg fresco; tecidos compartilham tanques.','Published counts;censoring is not zero.LOD1.6 µg/kg fresh weight;tissues share tanks.'))],'source_url':src[4]['url']}]
